     1	// The service fulfills asynchronously with false (pending) or true (ready).
     2	// Timers run on a later turn; the host owns scheduling, not response policy.
     3	class Resource {
     4	  constructor(host, token, notify = () => {}) {
     5	    this.host=host; this.notify=notify; this.generation=0; this.timer=null; this.disposed=false; this.clearLoadingOnDispose=this instanceof DialogResource||false;
     6	    this.state={visible:true,loading:false,retryScheduled:false,checkCount:0,completed:[],token};
     7	  }
     8	  snapshot(){return {...this.state,completed:[...this.state.completed]};}
     9	  publish(){if(!this.disposed){this.host.publish(this.snapshot());this.notify(this.snapshot());}}
    10	  cancelRetry(){if(this.timer!==null)this.host.cancel(this.timer);this.timer=null;this.state.retryScheduled=false;}
    11	  invalidate(){this.generation++;this.cancelRetry(); this.state.loading=false;}
    12	  start(){this.invalidate();this.state.visible=true;this.check(this.generation);}
    13	  reopen(token){this.invalidate();this.state.token=token;this.state.visible=true;this.check(this.generation);}
    14	  check(generation){
    15	    const token=this.state.token;
    16	    this.state.loading=true;this.state.checkCount++;this.publish();
    17	    this.host.check(token).then(ready=>{
    18	      if(this.disposed||generation!==this.generation)return;
    19	      if(ready===true){
    20	        this.cancelRetry();this.state.loading=false;
    21	        if(!this.state.completed.includes(token))this.state.completed.push(token);
    22	        this.publish();
    23	      }else{this.pending(generation);}
    24	    });
    25	  }
    26	  schedule(generation){
    27	    this.state.retryScheduled=true;
    28	    this.timer=this.host.schedule(()=>{
    29	      if(this.disposed||generation!==this.generation)return;
    30	      this.timer=null;this.state.retryScheduled=false;this.check(generation);
    31	    });this.publish();
    32	  }
    33	  dispose(){this.disposed=true;this.generation++;this.cancelRetry();if(this.clearLoadingOnDispose)this.state.loading=false;}
    34	}
    35	export class DialogResource extends Resource {
    36	  pending(generation){this.publish();}
    37	  close(){this.state.visible=false;this.invalidate();this.publish();}
    38	}
    39	export class WorkspaceJob extends Resource {
    40	    start(){this.check(this.generation);}
    41	  pending(generation){this.schedule(generation);}
    42	  close(){this.state.visible=false; this.publish();}
    43	}
    44	export function createResource(host,surface,token,notify){
    45	  return surface==='download'?new DialogResource(host,token,notify):new WorkspaceJob(host,token,notify);
    46	}
